      "path": "src/index.ts",
      "content": "/**
 * dsh-dep-vuln-scan plugin assembly: registers the `dep_vuln_scan` tool and a
 * one-line system-prompt guidance section that tells the model when and how to
 * use it. Both registrations are effect-based — disposing the plugin fiber
 * unregisters them.
 *
 * Composition contract: `name`/`inject`/`apply` is the Cordis plugin shape the
 * loader expects; rows in `cordis.yml` mount this module by package name
 * (`dsh-dep-vuln-scan/lib/index.js`).
 *
 * @module dsh-dep-vuln-scan
 */

import type { Context } from '@deepseek-ai/cordis'
// Brings the `ctx.systemPrompt` service augmentation into scope (type-only).
import type {} from '@deepseek-ai/dsh-system-prompt'
import { defineDepScanTool } from './tools/dep-scan.js'

/** Cordis plugin name used by loader diagnostics. */
export const name = 'dsh-dep-vuln-scan'

/** Hard dependencies: tools (registration), fs (lockfile reads), systemPrompt (guidance). */
export const inject = ['tools', 'fs', 'systemPrompt']

export function apply(ctx: Context): void {
  ctx.systemPrompt.section({
    name: 'tool:dep_vuln_scan',
    order: 111,
    text:
      'Use the dep_vuln_scan tool to audit a project’s dependency lockfiles '
      + '(npm/pnpm/yarn/pip/go/cargo/maven/gradle/nuget/rubygems) against the free OSV '
      + 'vulnerability database. It returns confirmed findings with CVSS scores and fix '
      + 'versions plus remediation commands — read-only, it never modifies lockfiles.',
  })

  ctx.tools.register(defineDepScanTool(ctx))
}"
    },
    {
      "path": "src/tools/dep-scan.ts",
      "content": "/**
 * `dep_vuln_scan` tool definition and the scan orchestration behind it.
 *
 * The orchestration (`runDepScan`) talks to the filesystem through the
 * `FsAdapter` seam and to OSV through the injectable `OsvTransport`, so the
 * smoke tests can drive the full pipeline offline against an in-memory
 * filesystem and a recorded-response HTTP stub. The `defineTool` wrapper
 * adapts `ctx.fs` to that seam when the tool executes inside DSH.
 *
 * Read-only by design: the scanner never writes, edits, or installs — it only
 * reports remediation commands for the user to run with confirmation
 * (PRIMARY spec: "不写任何文件（只读分析）").
 *
 * @module dsh-dep-vuln-scan/tools/dep-scan
 */

import type { Context } from '@deepseek-ai/cordis'
import type { FsDirEntry, FsTarget } from '@deepseek-ai/dsh-fs'
import { defineTool } from '@deepseek-ai/dsh-tools'
import {
  ecosystemForFile,
  parseLockfile,
  SKIP_DIRECTORIES,
  type PackageEntry,
  type ParsedLockfile,
} from '../lockfile-parsers.js'
import {
  queryOsvBatch,
  type NormalizedVuln,
  type OsvFailure,
  type OsvQueryPackage,
  type OsvTransport,
} from '../osv-client.js'
import {
  buildReport,
  buildPresentationMeta,
  renderMarkdown,
  type ScannedLockfile,
  type ScanReport,
} from '../report.js'

/** Minimal filesystem surface the scan core needs (subset of `ctx.fs`). */
export interface FsAdapterTarget {
  /**
   * Opaque backend identity for follow-up calls. The real adapter stores the
   * backend's own `FsTarget`; tests store whatever they need. Never parsed.
   */
  handle: unknown
  /** Path for model/UI-facing output. */
  displayPath: string
}

export interface FsAdapterDirEntry {
  name: string
  type: 'file' | 'directory' | 'other'
  target: FsAdapterTarget
}

export interface FsAdapter {
  resolve(path: string): Promise<FsAdapterTarget>
  stat(target: FsAdapterTarget): Promise<{ type: 'file' | 'directory' | 'other' } | undefined>
  listDir(target: FsAdapterTarget): Promise<FsAdapterDirEntry[]>
  readText(target: FsAdapterTarget): Promise<string>
}

/** The opaque handle stored for a real ctx.fs target. */
interface CtxFsHandle {
  target: FsTarget
}

/** Adapt the real `ctx.fs` service to {@link FsAdapter}. */
export function adaptCtxFs(ctx: Context): FsAdapter {
  const toTarget = (target: FsAdapterTarget): FsTarget => {
    const handle = target.handle as CtxFsHandle
    return handle.target
  }
  return {
    async resolve(path) {
      const target = await ctx.fs.resolve(path)
      return { handle: { target } satisfies CtxFsHandle, displayPath: target.displayPath }
    },
    async stat(target) {
      const info = await ctx.fs.stat(toTarget(target))
      if (info === undefined) return undefined
      return { type: info.type }
    },
    async listDir(target) {
      const entries = await ctx.fs.listDir(toTarget(target))
      return entries.map((entry: FsDirEntry) => ({
        name: entry.name,
        type: entry.type,
        target: { handle: { target: entry.target } satisfies CtxFsHandle, displayPath: entry.target.displayPath },
      }))
    },
    async readText(target) {
      return ctx.fs.readText(toTarget(target))
    },
  }
}

/** Accepted `dep_vuln_scan` arguments (mirrors the defineTool parameters). */
export interface DepScanArgs {
  /** Project directory or lockfile path; defaults to the workspace root. */
  path?: string
  /** Ecosystem filter (user-facing names, case-insensitive). */
  ecosystems?: string[]
  /** fast = root lockfiles, concurrency 4, no SBOM; full = recursive, concurrency 16, SBOM. */
  effort?: 'fast' | 'full'
}

export interface RunDepScanOptions {
  fs: FsAdapter
  transport?: OsvTransport
  signal?: AbortSignal
}

/** User-facing ecosystem name → canonical OSV ecosystem. */
const ECOSYSTEM_ALIASES: Readonly<Record<string, string>> = {
  npm: 'npm', node: 'npm', nodejs: 'npm', js: 'npm',
  pypi: 'PyPI', pip: 'PyPI', python: 'PyPI',
  go: 'Go', golang: 'Go',
  crates: 'crates.io', cargo: 'crates.io', rust: 'crates.io',
  maven: 'Maven', java: 'Maven', gradle: 'Maven',
  nuget: 'NuGet', dotnet: 'NuGet', csharp: 'NuGet',
  rubygems: 'RubyGems', gem: 'RubyGems', ruby: 'RubyGems',
}

/** `effort` → OSV batch concurrency (fast: 4, full: 16). */
export function concurrencyForEffort(effort: 'fast' | 'full'): number {
  return effort === 'full' ? 16 : 4
}

const MAX_DISCOVERY_DEPTH = 8
const MAX_LOCKFILES = 200

/**
 * The whole scan: resolve root, discover + parse lockfiles, filter by
 * ecosystem, run the OSV batch query, and assemble the report. Expected
 * failures (network, parse, rate limits) land in `report.errors`; the function
 * only throws for genuinely broken inputs.
 */
export async function runDepScan(args: DepScanArgs, options: RunDepScanOptions): Promise<ScanReport> {
  const { fs, transport, signal } = options
  const effort = args.effort ?? 'fast'
  const rootPath = args.path ?? '.'
  const root = await fs.resolve(rootPath)
  const rootInfo = await fs.stat(root)
  const errors: OsvFailure[] = []
  const lockfiles: ScannedLockfile[] = []
  const packageBuckets = new Map<string, PackageEntry[]>()

  const collect = (parsed: ParsedLockfile, displayPath: string) => {
    if (parsed.ecosystem === 'unknown') {
      errors.push({
        kind: 'parse',
        message: `无法识别锁文件类型: ${parsed.fileName}`,
        retryable: false,
      })
      return
    }
    if (parsed.parseError !== undefined) {
      errors.push({
        kind: 'parse',
        message: `解析失败 ${parsed.fileName}: ${parsed.parseError}`,
        retryable: false,
      })
    }
    lockfiles.push({ ecosystem: parsed.ecosystem, path: displayPath, packageCount: parsed.entries.length })
    const bucket = packageBuckets.get(parsed.ecosystem) ?? []
    bucket.push(...parsed.entries)
    packageBuckets.set(parsed.ecosystem, bucket)
  }

  if (rootInfo === undefined) {
    errors.push({ kind: 'parse', message: `路径不存在: ${root.displayPath}`, retryable: false })
    return buildReport({ effort, root: root.displayPath, lockfiles, queries: [], vulnsByQuery: [], errors })
  }

  if (rootInfo.type === 'file') {
    const fileName = basename(root.displayPath)
    const content = await fs.readText(root)
    const parsed = parseLockfile(fileName, content)
    collect(parsed, root.displayPath)
  } else if (rootInfo.type === 'directory') {
    const discovered = await discoverDirectory(fs, root, effort, 0, signal)
    for (const file of discovered) {
      const fileName = basename(file.target.displayPath)
      const content = await fs.readText(file.target)
      const parsed = parseLockfile(fileName, content)
      collect(parsed, file.target.displayPath)
    }
  } else {
    errors.push({
      kind: 'parse',
      message: `路径不是常规文件或目录: ${root.displayPath}`,
      retryable: false,
    })
  }

  // Ecosystem filter (normalise user-facing names).
  const wanted = new Set((args.ecosystems ?? []).map((name) => ECOSYSTEM_ALIASES[name.toLowerCase()] ?? name))

  const queries: OsvQueryPackage[] = []
  for (const [ecosystem, entries] of packageBuckets) {
    if (wanted.size > 0 && !wanted.has(ecosystem)) continue
    for (const entry of entries) {
      queries.push({ name: entry.name, ecosystem, version: entry.version })
    }
  }

  const batch = await queryOsvBatch(queries, {
    transport,
    concurrency: concurrencyForEffort(effort),
    signal,
  })

  for (const failed of batch.failures) {
    const dedupeKey = `${failed.failure.kind}${failed.failure.status ?? ''}${failed.failure.message}`
    if (!errors.some((e) => `${e.kind}${e.status ?? ''}${e.message}` === dedupeKey)) {
      errors.push(failed.failure)
    }
  }

  const vulnsByQuery = batch.vulnsByQuery
  return buildReport({
    effort,
    root: root.displayPath,
    lockfiles,
    queries: batch.queries,
    vulnsByQuery,
    errors,
  })
}

/**
 * Recursively list lockfile files under a directory. `fast` scans the root
 * level only; `full` walks subdirectories (skipping `node_modules`/VCS/build
 * dirs) down to {@link MAX_DISCOVERY_DEPTH} and up to {@link MAX_LOCKFILES}
 * files, so even a large monorepo cannot explode the scan.
 */
async function discoverDirectory(
  fs: FsAdapter,
  target: FsAdapterTarget,
  effort: 'fast' | 'full',
  depth: number,
  signal?: AbortSignal,
): Promise<FsAdapterDirEntry[]> {
  const files: FsAdapterDirEntry[] = []
  const walk = async (dir: FsAdapterTarget, currentDepth: number): Promise<void> => {
    if (signal?.aborted === true) return
    if (currentDepth > MAX_DISCOVERY_DEPTH || files.length >= MAX_LOCKFILES) return
    const entries = await fs.listDir(dir)
    for (const entry of entries) {
      if (files.length >= MAX_LOCKFILES) return
      if (entry.type === 'directory') {
        if (SKIP_DIRECTORIES.has(entry.name)) continue
        if (effort === 'full') await walk(entry.target, currentDepth + 1)
        continue
      }
      if (entry.type === 'file' && ecosystemForFile(entry.name) !== null) {
        files.push(entry)
      }
    }
  }
  await walk(target, depth)
  return files
}

function basename(path: string): string {
  const normalized = path.replace(/\\/g, '/').replace(/\/+$/, '')
  const index = normalized.lastIndexOf('/')
  return index >= 0 ? normalized.slice(index + 1) : normalized
}

