    {
      "path": "src/lockfile-parsers.ts",
      "content": "/**
 * Lockfile parsers: turn each supported ecosystem's lockfile content into a
 * flat list of `(name, version)` package entries. Every parser is a pure
 * function of `(fileName, content)` so the smoke tests can drive them offline
 * and the tool layer can feed them `ctx.fs` reads.
 *
 * Coverage (OSV ecosystem in parentheses): npm `package-lock.json` /
 * `pnpm-lock.yaml` / `yarn.lock` (npm), Python `requirements.txt` /
 * `Pipfile.lock` / `poetry.lock` (PyPI), Go `go.mod` (Go), Rust `Cargo.lock`
 * (crates.io), JVM `pom.xml` / `build.gradle*` (Maven), NuGet
 * `packages.lock.json` (NuGet), Ruby `Gemfile.lock` (RubyGems).
 *
 * Scope/limits (documented in README): pnpm/yarn are parsed line-wise and may
 * miss exotic resolutions; `pom.xml`/gradle only recognise literal versions
 * (variables like `${revision}` are skipped); indirect transitivity is not
 * resolved — the scan reports what the lockfile records.
 *
 * @module dsh-dep-vuln-scan/lockfile-parsers
 */

export interface PackageEntry {
  /** Package name as recorded by the lockfile (Maven: `group:artifact`). */
  name: string
  /** Exact locked version string, as recorded (Maven/Gradle may include a qualifier). */
  version: string
}

export interface ParsedLockfile {
  /** Basename of the lockfile, as passed in. */
  fileName: string
  /** OSV ecosystem name the lockfile maps to. */
  ecosystem: string
  /** Parsed entries, deduplicated by `name+version`. */
  entries: PackageEntry[]
  /** Set when the file was recognised but its content could not be parsed. */
  parseError?: string
}

/** Filename → OSV ecosystem. Keys are lowercase; a file may match several (`.lock` variants). */
export const LOCKFILE_ECOSYSTEM: Readonly<Record<string, string>> = {
  'package-lock.json': 'npm',
  'pnpm-lock.yaml': 'npm',
  'yarn.lock': 'npm',
  'requirements.txt': 'PyPI',
  'pipfile.lock': 'PyPI',
  'poetry.lock': 'PyPI',
  'go.mod': 'Go',
  'cargo.lock': 'crates.io',
  'pom.xml': 'Maven',
  'build.gradle': 'Maven',
  'build.gradle.kts': 'Maven',
  'packages.lock.json': 'NuGet',
  'gemfile.lock': 'RubyGems',
}

/** Directory names a recursive discovery must never descend into. */
export const SKIP_DIRECTORIES: ReadonlySet<string> = new Set([
  'node_modules', '.git', '.svn', '.hg', 'dist', 'build', 'out', 'coverage',
  'vendor', '.venv', 'venv', '__pycache__', '.gradle', '.mvn', 'target',
])

/** Resolve the OSV ecosystem for a file basename, or `null` when unsupported. */
export function ecosystemForFile(fileName: string): string | null {
  const key = fileName.toLowerCase()
  return LOCKFILE_ECOSYSTEM[key] ?? null
}

/**
 * Parse one lockfile's content by file name. Unsupported or unparsable files
 * return an empty entry list (callers surface parse errors through the report
 * when they care, but a scan must never throw on a single odd file).
 */
export function parseLockfile(fileName: string, content: string): ParsedLockfile {
  const key = fileName.toLowerCase()
  const ecosystem = LOCKFILE_ECOSYSTEM[key]
  if (ecosystem === undefined) {
    return { fileName, ecosystem: 'unknown', entries: [] }
  }
  let entries: PackageEntry[]
  let parseError: string | undefined
  try {
    entries = parseForEcosystem(ecosystem, key, content)
  } catch (err) {
    // A malformed lockfile must not abort the whole scan; surface it instead.
    entries = []
    parseError = err instanceof Error ? err.message : String(err)
  }
  return { fileName, ecosystem, entries: dedupeEntries(entries), parseError }
}

function parseForEcosystem(ecosystem: string, key: string, content: string): PackageEntry[] {
  switch (ecosystem) {
    case 'npm': {
      if (key === 'package-lock.json') return parseNpmPackageLock(content)
      if (key === 'pnpm-lock.yaml') return parsePnpmLock(content)
      return parseYarnLock(content)
    }
    case 'PyPI': {
      if (key === 'requirements.txt') return parseRequirementsTxt(content)
      if (key === 'pipfile.lock') return parsePipfileLock(content)
      return parsePoetryLock(content)
    }
    case 'Go':
      return parseGoMod(content)
    case 'crates.io':
      return parseCargoLock(content)
    case 'Maven': {
      if (key === 'pom.xml') return parsePomXml(content)
      return parseGradleLock(content)
    }
    case 'NuGet':
      return parsePackagesLockJson(content)
    case 'RubyGems':
      return parseGemfileLock(content)
    default:
      return []
  }
}

function dedupeEntries(entries: PackageEntry[]): PackageEntry[] {
  const seen = new Set<string>()
  const out: PackageEntry[] = []
  for (const entry of entries) {
    const id = `${entry.name}\u0000${entry.version}`
    if (entry.name === '' || entry.version === '' || seen.has(id)) continue
    seen.add(id)
    out.push(entry)
  }
  return out
}

// ---------------------------------------------------------------------------
// npm
// ---------------------------------------------------------------------------

/**
 * Parse npm `package-lock.json` (lockfileVersion 1/2/3). Version ≥ 2 keeps a
 * `packages` map keyed by `node_modules/<path>`; v1 keeps a nested
 * `dependencies` map. Workspace-linked entries (`"link": true`) and entries
 * without a version are skipped.
 */
export function parseNpmPackageLock(content: string): PackageEntry[] {
  const data = JSON.parse(content) as {
    packages?: Record<string, { version?: string; link?: boolean }>
    dependencies?: Record<string, { version?: string }>
  }
  const entries: PackageEntry[] = []

  if (data.packages !== undefined && data.packages !== null) {
    const packages = data.packages
    for (const [pathKey, value] of Object.entries(packages)) {
      if (pathKey === '' || value.link === true) continue
      const normalized = normalizeNpmPath(pathKey)
      const name = normalized.name
      const version = typeof value.version === 'string' ? value.version : undefined
      if (name === '' || version === undefined || version === '') continue
      entries.push({ name, version })
    }
    return entries
  }

  if (data.dependencies !== undefined) {
    const walk = (deps: Record<string, { version?: string; dependencies?: typeof deps }>) => {
      for (const [name, value] of Object.entries(deps)) {
        const version = typeof value.version === 'string' ? value.version : undefined
        if (version !== undefined && version !== '') entries.push({ name, version })
        if (value.dependencies !== undefined && value.dependencies !== null) walk(value.dependencies)
      }
    }
    walk(data.dependencies)
  }
  return entries
}

/**
 * `node_modules/a/node_modules/b` → the innermost package name; scoped names
 * like `node_modules/@scope/pkg` keep their `@scope/` prefix.
 */
function normalizeNpmPath(pathKey: string): { name: string } {
  const segments = pathKey.split('node_modules/')
  // trim an empty leading segment (path starts with `node_modules/`)
  while (segments.length > 0 && segments[0] === '') segments.shift()
  const last = segments[segments.length - 1] ?? ''
  return { name: last.replace(/\/+$/, '') }
}

/**
 * Parse `pnpm-lock.yaml` package entries ("best effort", no YAML dependency):
 * inside the top-level `packages:` section, 2-space-indented keys of the form
 * `/name@version(...)` (scoped names included) yield `(name, version)` pairs.
 * Peer-dependency suffixes `(dep@x)` and build metadata (`+sha512...`) are
 * stripped.
 */
export function parsePnpmLock(content: string): PackageEntry[] {
  const lines = content.split(/\r?\n/)
  const entries: PackageEntry[] = []
  let inPackages = false

  const header = /^\s{0,2}packages\s*:\s*$/
  const entry = /^\s{2}\/(?<name>@?[^@\s/:]+(?:\/[^@\s/:]+)*)@(?<version>[^\s():]+)(?:\([^)]*\))?\s*:\s*$/

  for (const line of lines) {
    if (inPackages) {
      // A top-level key (no leading whitespace) ends the packages section.
      if (!/^\s/.test(line)) {
        if (header.test(line)) continue // `packages:` can repeat across sections
        inPackages = false
        continue
      }
      const match = entry.exec(line)
      if (match === null || match.groups === undefined) continue
      const version = (match.groups.version ?? '').split('+')[0] ?? ''
      if (version === '') continue
      entries.push({ name: match.groups.name ?? '', version })
    } else if (header.test(line)) {
      inPackages = true
    }
  }
  return entries
}

/**
 * Parse a classic (v1) `yarn.lock`: entry headers like
 * `"@babel/code-frame@^7.0.0":` or `lodash@^4.17.21:` are followed by a
 * two-space-indented `version "1.2.3"` line. Berry lockfiles (with
 * `__metadata:`) are not supported and yield an empty list.
 */
export function parseYarnLock(content: string): PackageEntry[] {
  if (content.includes('__metadata:')) return []
  const lines = content.split(/\r?\n/)
  const entries: PackageEntry[] = []
  const header = /^"?(@?[^"@\s]+(?:\/[^"@\s]+)?)@[^"\s]+"?:\s*$/
  const versionLine = /^\s{2}version "([^"]+)"\s*$/
  let pendingName: string | null = null

  for (const line of lines) {
    const versionMatch = versionLine.exec(line)
    if (versionMatch !== null && pendingName !== null) {
      entries.push({ name: pendingName, version: versionMatch[1] ?? '' })
      pendingName = null
      continue
    }
    const headerMatch = header.exec(line)
    if (headerMatch !== null) {
      pendingName = headerMatch[1] ?? null
    }
  }
  return entries
}

// ---------------------------------------------------------------------------
// PyPI
// ---------------------------------------------------------------------------

/**
 * Parse a pip `requirements.txt`: `pkg==1.2.3` lines (with optional extras and
 * environment markers stripped). Non-exact specifiers (`>=`, `~=`, bare names)
 * are skipped because OSV needs an exact version.
 */
export function parseRequirementsTxt(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  const linePattern = /^\s*([A-Za-z0-9_.\-]+)(?:\[[^\]]*\])?\s*==\s*([0-9][A-Za-z0-9.+\-]*)/i
  for (const rawLine of content.split(/\r?\n/)) {
    const line = (rawLine.split('#')[0] ?? '').split(';')[0] ?? ''
    const match = linePattern.exec(line)
    if (match === null) continue
    // names are case-insensitive on PyPI; keep the recorded casing for display
    entries.push({ name: match[1] ?? '', version: match[2] ?? '' })
  }
  return entries
}

/**
 * Parse a Pipenv `Pipfile.lock`: dependencies live in `default` and `develop`
 * maps with `"version": "==1.2.3"` / `"*"` values. Non-exact versions are
 * skipped.
 */
export function parsePipfileLock(content: string): PackageEntry[] {
  const data = JSON.parse(content) as {
    default?: Record<string, { version?: string }>
    develop?: Record<string, { version?: string }>
  }
  const entries: PackageEntry[] = []
  const collect = (section: Record<string, { version?: string }> | undefined) => {
    if (section === undefined) return
    for (const [name, spec] of Object.entries(section)) {
      const version = typeof spec.version === 'string' ? spec.version : undefined
      if (version === undefined) continue
      const exact = /^==\s*(.+)$/.exec(version.trim())
      if (exact === null) continue
      entries.push({ name, version: exact[1] ?? '' })
    }
  }
  collect(data.default)
  collect(data.develop)
  return entries
}

/**
 * Parse a Poetry `poetry.lock` (TOML): split on `[[package]]` blocks and read
 * the first `name = "..."` / `version = "..."` pair of each block.
 */
export function parsePoetryLock(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  for (const block of content.split(/\n\[\[package\]\]/)) {
    const nameMatch = /^\s*name\s*=\s*"([^"]+)"/m.exec(block)
    const versionMatch = /^\s*version\s*=\s*"([^"]+)"/m.exec(block)
    if (nameMatch === null || versionMatch === null) continue
    entries.push({ name: nameMatch[1] ?? '', version: versionMatch[1] ?? '' })
  }
  return entries
}

// ---------------------------------------------------------------------------
// Go
// ---------------------------------------------------------------------------

/**
 * Parse `go.mod` `require` directives — inline (`require mod v1.2.3`) and
 * block form. Comment lines are stripped first. Indirect requirements are
 * included (they are real locked versions; the report marks them via OSV).
 */
export function parseGoMod(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  const cleaned = content.replace(/\/\/.*$/gm, '').replace(/\r/g, '')
  const lines = cleaned.split('\n')
  let inRequireBlock = false

  for (const raw of lines) {
    const line = raw.trim()
    if (line === '') continue
    if (line === 'require (') {
      inRequireBlock = true
      continue
    }
    if (inRequireBlock && line === ')') {
      inRequireBlock = false
      continue
    }
    if (line.startsWith('require ')) {
      const rest = line.slice('require '.length).trim()
      const pair = splitGoRequirement(rest)
      if (pair !== null) entries.push(pair)
      continue
    }
    if (inRequireBlock) {
      const pair = splitGoRequirement(line)
      if (pair !== null) entries.push(pair)
    }
  }
  return entries
}

/** Split one `modulepath version` pair; validates the version starts with `v`. */
function splitGoRequirement(line: string): PackageEntry | null {
  const parts = line.split(/\s+/).filter((p) => p !== '')
  if (parts.length !== 2) return null
  const modulePath = parts[0] ?? ''
  const version = parts[1] ?? ''
  if (!modulePath.includes('/')) return null // `go 1.21` / toolchain lines
  if (!/^v\d+\.\d+\.\d+/.test(version)) return null
  return { name: modulePath, version }
}

// ---------------------------------------------------------------------------
// crates.io / Rust
// ---------------------------------------------------------------------------

/**
 * Parse a Cargo `Cargo.lock` (TOML): split on `[[package]]` blocks and read
 * each block's `name` + `version`.
 */
export function parseCargoLock(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  for (const block of content.split(/\n\[\[package\]\]/)) {
    const nameMatch = /^\s*name\s*=\s*"([^"]+)"/m.exec(block)
    const versionMatch = /^\s*version\s*=\s*"([^"]+)"/m.exec(block)
    if (nameMatch === null || versionMatch === null) continue
    entries.push({ name: nameMatch[1] ?? '', version: versionMatch[1] ?? '' })
  }
  return entries
}

// ---------------------------------------------------------------------------
// Maven / Gradle
// ---------------------------------------------------------------------------

/**
 * Parse a Maven `pom.xml`: inside `<dependencies>`, capture
 * `groupId`/`artifactId`/`version` triples in document order and emit
 * `group:artifact` → version. Literal versions only; `${...}` properties and
 * `$`-free managed versions are skipped. Dependency-management duplicates are
 * later deduplicated by the caller.
 */
export function parsePomXml(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  // Strip comments so they cannot bridge the triple regex.
  const cleaned = content.replace(/<!--[\s\S]*?-->/g, '')
  const tagValues = [
    ...cleaned.matchAll(/<\s*(groupId|artifactId|version)\s*>([^<]+?)<\s*\/\s*\1\s*>/gi),
  ]
  const bucket: string[] = []
  for (const match of tagValues) {
    const value = (match[2] ?? '').trim()
    bucket.push(value)
    if (bucket.length === 3) {
      const [groupId, artifactId, version] = bucket
      bucket.length = 0
      if (groupId === undefined || artifactId === undefined || version === undefined) continue
      if (version.trimStart().startsWith('$')) continue
      if (groupId !== '' && artifactId !== '' && version !== '') {
        entries.push({ name: `${groupId}:${artifactId}`, version })
      }
    }
  }
  return entries
}

/**
 * Parse a Gradle `build.gradle[.kts]` for string coordinates
 * `group:artifact:version` (single or double quotes, any plugin/app/api block).
 * Versions that reference variables (`$project.xxx`, `libs.versions...`) are
 * skipped.
 */
export function parseGradleLock(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  const pattern = /['"](?<group>[A-Za-z0-9_.\-]+):(?<artifact>[A-Za-z0-9_.\-]+):(?<version>[A-Za-z0-9_.\-]+)['"]/g
  for (const match of content.matchAll(pattern)) {
    const version = match.groups?.version ?? ''
    if (version.startsWith('$')) continue
    const name = `${match.groups?.group ?? ''}:${match.groups?.artifact ?? ''}`
    if (name === ':' || version === '') continue
    entries.push({ name, version })
  }
  return entries
}

// ---------------------------------------------------------------------------
// NuGet / RubyGems
// ---------------------------------------------------------------------------

/**
 * Parse a NuGet `packages.lock.json`: the `dependencies` map holds
 * `"pkg": { "resolved": "1.2.3", ... }`. Framework dependencies (`.NETCoreApp`)
 * are normal packages and included.
 */
export function parsePackagesLockJson(content: string): PackageEntry[] {
  const data = JSON.parse(content) as {
    dependencies?: Record<string, Record<string, { resolved?: string }>>
  }
  const entries: PackageEntry[] = []
  if (data.dependencies === undefined) return entries
  for (const frameworkGroups of Object.values(data.dependencies)) {
    if (frameworkGroups === undefined) continue
    for (const [name, value] of Object.entries(frameworkGroups)) {
      const resolved = typeof value?.resolved === 'string' ? value.resolved : undefined
      if (resolved === undefined || resolved === '') continue
      entries.push({ name, version: resolved })
    }
  }
  return entries
}

/**
 * Parse a Bundler `Gemfile.lock`: four-space-indented gem lines
 * `    rails (7.0.4)` under each dependency section. Excludes the leading
 * `GIT`/`PATH`/`PLATFORMS` markers naturally (they are not `name (version)`).
 */
export function parseGemfileLock(content: string): PackageEntry[] {
  const entries: PackageEntry[] = []
  const pattern = /^\s{4}([A-Za-z0-9_.\-]+) \(([^)]+)\)\s*$/gm
  for (const match of content.matchAll(pattern)) {
    const name = match[1] ?? ''
    const version = match[2] ?? ''
    if (name === '' || version === '') continue
    entries.push({ name, version })
  }
  return entries
}"
