      "path": "src/osv-client.ts",
      "content": "/**
 * OSV (osv.dev) batch-query client: chunked `POST /v1/querybatch` calls with a
 * concurrency-limited pool, per-request timeout, bounded retries with backoff,
 * and a structured error taxonomy so a failed scan never blocks the session.
 *
 * The transport is injectable (`OsvTransport`) so the smoke tests can point the
 * whole pipeline at a local HTTP stub serving recorded responses — the client
 * code path (chunking, retry, parse, normalisation) is exercised offline.
 *
 * Why not `ctx.web`? The web seam (`dsh-web`) only supports GET-style fetch of
 * HTML/text bodies; OSV's batch endpoint requires a `POST` with a JSON body.
 * The default transport therefore uses the host process's global `fetch` — the
 * exact transport the bundled `web-fetch-http` provider uses — and honours the
 * caller's `AbortSignal` like the seam does.
 *
 * @module dsh-dep-vuln-scan/osv-client
 */

import { minVersion, parseSemver, versionInRange } from './semver.js'

/** Batch endpoint and safe request bounds. */
export const OSV_BATCH_URL = 'https://api.osv.dev/v1/querybatch'
/** 单条漏洞详情端点（两段式回查：batch 只回 id，详情按 id 逐个取）。 */
export const OSV_VULN_URL = 'https://api.osv.dev/v1/vulns'
export const OSV_QUERY_CHUNK_SIZE = 250
export const OSV_DEFAULT_TIMEOUT_MS = 30_000
export const OSV_MAX_ATTEMPTS = 2 // first + one retry

/** One package to query. `version` makes OSV return only confirmed-hit vulns. */
export interface OsvQueryPackage {
  name: string
  ecosystem: string
  version: string
}

export interface OsvEvent {
  introduced?: string
  fixed?: string
  last_affected?: string
}

export interface OsvRange {
  /** Range type discriminator (`SEMVER`, `ECOSYSTEM`, ...) — informational. */
  type?: string
  events?: OsvEvent[]
}

export interface OsvDatabaseSpecific {
  severity?: string
  cvss_v3?: { baseScore?: number }
}

export interface OsvAffected {
  package?: { name?: string; ecosystem?: string }
  ranges?: OsvRange[]
  versions?: string[]
  database_specific?: OsvDatabaseSpecific
}

export interface OsvVulnerability {
  id: string
  /** 详情面字段（batch 查询面只回 id+modified，详情回查后填充）。 */
  modified?: string
  aliases?: string[]
  summary?: string
  details?: string
  database_specific?: OsvDatabaseSpecific
  affected?: OsvAffected[]
}

/** Normalised, report-ready vulnerability derived from one OSV record. */
export interface NormalizedVuln {
  /** OSV id (e.g. `GHSA-xxxx` or `GO-2021-xxxx`). */
  id: string
  /** Raw aliases, when present. */
  aliases: string[]
  /** Preferred display id: first CVE-/GHSA- alias, else `id`. */
  displayId: string
  /** The CVE alias, if any. */
  cve: string | undefined
  /** The GHSA alias, if any. */
  ghsa: string | undefined
  /** OSV summary, truncated to 120 characters. */
  summary: string
  /** Numeric CVSS base score when the OSV record carries one. */
  cvss: number | undefined
  /** Qualitative severity ('critical'|'high'|'medium'|'low'|'unknown'). */
  severity: Severity
  /** Earliest `fixed` version across the affected ranges that cover the current version. */
  fixedVersion: string | undefined
  /** True when `fixedVersion` exists. */
  hasFix: boolean
}

export type Severity = 'critical' | 'high' | 'medium' | 'low' | 'unknown'

export type OsvFailureKind = 'network' | 'timeout' | 'http' | 'ratelimit' | 'invalid-response' | 'parse'

/** Structured, user-facing error with a double hint (`检测网络` / `稍后重试`). */
export interface OsvFailure {
  kind: OsvFailureKind
  /** Human message; the network variant carries the acceptance-wording hint. */
  message: string
  /** HTTP status when the failure came from a non-2xx response. */
  status?: number
  retryable: boolean
}

/**
 * HTTP transport seam. `postJson` 是批量查询面，`getJson` 是回查详情面（真实
 * OSV `querybatch` 只回 `{id, modified}`，必须按 id 再 `GET /v1/vulns/{id}`
 * 取详情；库内已核实该响应形态）。测试用本地 stub 替换两者。
 */
export interface OsvTransport {
  postJson(
    url: string,
    body: unknown,
    opts: { signal?: AbortSignal; timeoutMs?: number },
  ): Promise<{ status: number; bodyText: string }>
  getJson(
    url: string,
    opts: { signal?: AbortSignal; timeoutMs?: number },
  ): Promise<{ status: number; bodyText: string }>
}

/** Transport rejection used internally to carry classification info. */
class TransportError extends Error {
  constructor(
    message: string,
    readonly failure: OsvFailure,
  ) {
    super(message)
    this.name = 'TransportError'
  }
}

/**
 * Default transport over the host's global `fetch` (Node ≥ 18; same surface as
 * the bundled `web-fetch-http` provider). Timeout is applied with
 * `AbortSignal.timeout` merged with the caller's signal.
 */
export const defaultFetchTransport: OsvTransport = {
  async getJson(url, opts) {
    const { signal, timeoutMs } = opts
    const timeout = AbortSignal.timeout(timeoutMs ?? OSV_DEFAULT_TIMEOUT_MS)
    const merged = mergeSignals(signal, timeout)
    let response: Response
    try {
      response = await fetch(url, { method: 'GET', signal: merged })
    } catch (err) {
      if (merged.aborted && signal?.aborted) {
        throw new TransportError('扫描已取消', { kind: 'timeout', message: '扫描已取消', retryable: false })
      }
      if (merged.aborted) {
        throw new TransportError('OSV 请求超时', {
          kind: 'timeout',
          message: 'OSV 请求超时，请检查网络或稍后重试',
          retryable: true,
        })
      }
      throw new TransportError('无法访问 OSV', {
        kind: 'network',
        message: '无法访问 OSV，检查网络或稍后重试',
        retryable: true,
      })
    }
    return { status: response.status, bodyText: await response.text() }
  },
  async postJson(url, body, opts) {
    const { signal, timeoutMs } = opts
    const timeout = AbortSignal.timeout(timeoutMs ?? OSV_DEFAULT_TIMEOUT_MS)
    const merged = mergeSignals(signal, timeout)
    let response: Response
    try {
      response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body),
        signal: merged,
      })
    } catch (err) {
      if (merged.aborted && signal?.aborted) {
        throw new TransportError('扫描已取消', { kind: 'timeout', message: '扫描已取消', retryable: false })
      }
      if (merged.aborted) {
        throw new TransportError('OSV 请求超时', {
          kind: 'timeout',
          message: 'OSV 请求超时，请检查网络或稍后重试',
          retryable: true,
        })
      }
      throw new TransportError('无法访问 OSV', {
        kind: 'network',
        message: '无法访问 OSV，检查网络或稍后重试',
        retryable: true,
      })
    }
    return { status: response.status, bodyText: await response.text() }
  },
}

/** Combine an optional caller signal with the timeout signal. */
export function mergeSignals(a: AbortSignal | undefined, b: AbortSignal): AbortSignal {
  if (a === undefined) return b
  if (a.aborted) return a
  const controller = new AbortController()
  const onAbort = () => controller.abort()
  a.addEventListener('abort', onAbort, { once: true })
  b.addEventListener('abort', onAbort, { once: true })
  return controller.signal
}

/** Raw response of one batch request, aligned with the submitted chunk. */
export interface BatchResponse {
  /** One element per submitted query; `null` when OSV found no vulns. */
  results: Array<{ vulns?: OsvVulnerability[] } | null>
}

/** Aggregate outcome of a full batch scan. */
export interface OsvBatchResult {
  /** Every unique package queried (post-deduplication). */
  queries: OsvQueryPackage[]
  /** Per-package normalised vulns, one element per `queries` entry. */
  vulnsByQuery: NormalizedVuln[][]
  /** Failures after retries, per query index. */
  failures: Array<{ index: number; query: OsvQueryPackage; failure: OsvFailure }>
  /** True when every query failed (report should emphasise the network hint). */
  allFailed: boolean
}

export interface QueryOsvOptions {
  transport?: OsvTransport
  concurrency?: number
  chunkSize?: number
  timeoutMs?: number
  maxAttempts?: number
  signal?: AbortSignal
}

/**
 * Run a batch scan over all packages. Chunks are queried through a bounded
 * pool (default 4 parallel requests; `effort: 'full'` raises it to 16). Each
 * chunk is retried up to `maxAttempts` with backoff on network/timeout/5xx and
 * respects `Retry-After` on 429. Individual chunk failures are recorded in
 * `failures` instead of throwing, so a partial outage degrades gracefully.
 */
export async function queryOsvBatch(
  packages: OsvQueryPackage[],
  options: QueryOsvOptions = {},
): Promise<OsvBatchResult> {
  const transport = options.transport ?? defaultFetchTransport
  const concurrency = options.concurrency ?? 4
  const chunkSize = options.chunkSize ?? OSV_QUERY_CHUNK_SIZE
  const timeoutMs = options.timeoutMs ?? OSV_DEFAULT_TIMEOUT_MS
  const maxAttempts = options.maxAttempts ?? OSV_MAX_ATTEMPTS
  const signal = options.signal

  if (packages.length === 0) {
    return { queries: [], vulnsByQuery: [], failures: [], allFailed: false }
  }

  // Deduplicate identical (ecosystem, name, version) queries.
  const seen = new Set<string>()
  const unique: OsvQueryPackage[] = []
  for (const pkg of packages) {
    const key = `${pkg.ecosystem}\u0000${pkg.name}\u0000${pkg.version}`
    if (seen.has(key)) continue
    seen.add(key)
    unique.push(pkg)
  }

  const chunks: OsvQueryPackage[][] = []
  for (let i = 0; i < unique.length; i += chunkSize) {
    chunks.push(unique.slice(i, i + chunkSize))
  }

  // 阶段 1：化整为零——querybatch 分批查询，真实响应只含 `{id, modified}`。
  const rawByQuery: Array<Array<{ id: string; modified?: string }> | null> = new Array(unique.length).fill(null)
  const failures: Array<{ index: number; query: OsvQueryPackage; failure: OsvFailure }> = []

  await runPool(chunks, concurrency, signal, async (chunk) => {
    const { vulns, failed } = await queryOneChunk(transport, chunk, {
      timeoutMs,
      maxAttempts,
      signal,
    })
    chunk.forEach((query, offset) => {
      const groupIndex = unique.indexOf(query)
      if (groupIndex < 0) return
      const raw = vulns[offset]
      if (raw !== undefined && raw !== null) {
        rawByQuery[groupIndex] = (raw.vulns ?? []).map((v) => ({ id: v.id, modified: v.modified }))
      }
    })
    for (const f of failed) {
      const groupIndex = unique.indexOf(f.query)
      if (groupIndex >= 0) failures.push({ index: groupIndex, query: f.query, failure: f.failure })
    }
  })

  // 阶段 2：详情回查——真实 OSV 的 batch 只回 id；逐个 `GET /v1/vulns/{id}` 取
  // 完整记录（aliases/affected/summary/severity），并发池 + 退避重试；单个详情
  // 失败记入 failures 并跳过该条，绝不让一次详情抖动拖垮整次扫描。
  const allIds: string[] = []
  for (const list of rawByQuery) {
    if (list === null) continue
    for (const entry of list) {
      if (!allIds.includes(entry.id)) allIds.push(entry.id)
    }
  }
  const detailMap = new Map<string, OsvVulnerability>()
  const detailIndexById = new Map<string, number>()
  allIds.forEach((id, idx) => detailIndexById.set(id, idx))
  await runPool(allIds, Math.max(2, concurrency), signal, async (id) => {
    let lastFailure: OsvFailure | undefined
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      if (signal?.aborted) break
      if (attempt > 0) await sleep(150 * attempt)
      try {
        const { bodyText, status } = await transport.getJson(
          `${OSV_VULN_URL}/${encodeURIComponent(id)}`,
          { signal, timeoutMs },
        )
        if (status === 200) {
          detailMap.set(id, JSON.parse(bodyText) as OsvVulnerability)
          return
        }
        if (status === 404) {
          lastFailure = { kind: 'invalid-response', message: `OSV 详情 404：${id}`, retryable: false }
          continue
        }
        if (status === 429 || status >= 500) {
          lastFailure = { kind: status === 429 ? 'ratelimit' : 'http', message: `OSV 详情 HTTP ${status}：${id}`, retryable: true, status }
          continue
        }
        lastFailure = { kind: 'http', message: `OSV 详情 HTTP ${status}：${id}`, retryable: false, status }
        continue
      } catch (error) {
        const transportError = error as { failure?: OsvFailure }
        lastFailure = transportError.failure ?? { kind: 'network', message: `OSV 详情失败：${id}`, retryable: true }
        continue
      }
    }
    // 详情重试用尽：记录失败（挂到该 id 对应的第一个查询上）并跳过该条。
    if (lastFailure !== undefined) {
      for (let qi = 0; qi < unique.length; qi++) {
        const list = rawByQuery[qi]
        if (list !== null && list.some((entry) => entry.id === id)) {
          failures.push({ index: qi, query: unique[qi], failure: { ...lastFailure, message: `${lastFailure.message}` } })
          break
        }
      }
    }
  })

  const perQueryVulns: Array<NormalizedVuln[] | null> = new Array(unique.length).fill(null)
  unique.forEach((query, index) => {
    const raw = rawByQuery[index]
    if (raw === null || raw === undefined) return
    const vulns: NormalizedVuln[] = []
    for (const entry of raw) {
      const detail = detailMap.get(entry.id)
      if (detail === undefined) continue // 详情失败已在 failures 记录
      vulns.push(normalizeVulnerability(detail, query.version))
    }
    perQueryVulns[index] = vulns
  })

  const results = unique.map(
    (query, index) => perQueryVulns[index] ?? [],
  )
  const allFailed = unique.length > 0 && failures.length >= unique.length
  return { queries: unique, vulnsByQuery: results, failures, allFailed }
}

/** 简单延迟（详情回查退避）。 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

/** Run `tasks` through a pool with at most `limit` concurrent in-flight items. */
export async function runPool<T>(
  tasks: readonly T[],
  limit: number,
  signal: AbortSignal | undefined,
  worker: (item: T, index: number) => Promise<void>,
): Promise<void> {
  const safeLimit = Math.max(1, Math.min(limit, 32))
  let cursor = 0
  const runners = Array.from({ length: safeLimit }, async () => {
    while (true) {
      if (signal?.aborted === true) {
        throw signal.reason ?? new Error('aborted')
      }
      const index = cursor
      cursor += 1
      if (index >= tasks.length) return
      await worker(tasks[index] as T, index)
    }
  })
  await Promise.all(runners)
}

/** One chunk query: payload build, attempt loop with backoff/Retry-After. */
async function queryOneChunk(
  transport: OsvTransport,
  chunk: OsvQueryPackage[],
  opts: { timeoutMs: number; maxAttempts: number; signal?: AbortSignal },
): Promise<{ vulns: Array<{ vulns?: OsvVulnerability[] } | null>; failed: Array<{ query: OsvQueryPackage; failure: OsvFailure }> }> {
  const payload = {
    queries: chunk.map((query) => ({
      package: { name: query.name, ecosystem: query.ecosystem },
      version: query.version,
    })),
  }

  let lastFailure: OsvFailure | null = null
  for (let attempt = 0; attempt < opts.maxAttempts; attempt++) {
    if (opts.signal?.aborted === true) break
    let response: { status: number; bodyText: string }
    try {
      response = await transport.postJson(OSV_BATCH_URL, payload, {
        signal: opts.signal,
        timeoutMs: opts.timeoutMs,
      })
    } catch (err) {
      lastFailure = err instanceof TransportError
        ? err.failure
        : { kind: 'network', message: '无法访问 OSV，检查网络或稍后重试', retryable: true }
      if (!lastFailure.retryable) break
      await sleepWithSignal(backoffMs(attempt), opts.signal)
      continue
    }

    if (response.status === 429) {
      lastFailure = {
        kind: 'ratelimit',
        message: 'OSV 接口限流（HTTP 429），请稍后重试',
        status: 429,
        retryable: true,
      }
      await sleepWithSignal(retryAfterMs(response.bodyText, attempt), opts.signal)
      continue
    }
    if (response.status >= 500) {
      lastFailure = {
        kind: 'http',
        message: `OSV 服务暂不可用（HTTP ${response.status}），请稍后重试`,
        status: response.status,
        retryable: true,
      }
      await sleepWithSignal(backoffMs(attempt), opts.signal)
      continue
    }
    if (response.status !== 200) {
      return {
        vulns: chunk.map(() => null),
        failed: chunk.map((query) => ({
          query,
          failure: {
            kind: 'http',
            message: `OSV 查询失败（HTTP ${response.status}），请稍后重试`,
            status: response.status,
            retryable: false,
          },
        })),
      }
    }

    let parsed: BatchResponse
    try {
      parsed = JSON.parse(response.bodyText) as BatchResponse
    } catch {
      return {
        vulns: chunk.map(() => null),
        failed: chunk.map((query) => ({
          query,
          failure: {
            kind: 'parse',
            message: 'OSV 返回了无法解析的响应，请稍后重试',
            retryable: true,
          },
        })),
      }
    }
    if (!Array.isArray(parsed.results) || parsed.results.length !== chunk.length) {
      return {
        vulns: chunk.map(() => null),
        failed: chunk.map((query) => ({
          query,
          failure: {
            kind: 'invalid-response',
            message: 'OSV 返回的响应结构异常，请稍后重试',
            retryable: true,
          },
        })),
      }
    }
    return { vulns: parsed.results, failed: [] }
  }

  if (lastFailure === null) {
    lastFailure = { kind: 'network', message: '无法访问 OSV，检查网络或稍后重试', retryable: true }
  }
  return {
    vulns: chunk.map(() => null),
    failed: chunk.map((query) => ({ query, failure: lastFailure! })),
  }
}

function backoffMs(attempt: number): number {
  return 500 + attempt * 500
}

function retryAfterMs(bodyText: string, attempt: number): number {
  const match = /"retry_after"\s*:\s*(\d+)/.exec(bodyText)
  if (match !== null) {
    const seconds = Number(match[1])
    if (Number.isFinite(seconds) && seconds > 0) return Math.min(seconds * 1000, 10_000)
  }
  return backoffMs(attempt + 1)
}

/** Sleep, aborting early when the signal fires (no unmanaged timers). */
function sleepWithSignal(ms: number, signal: AbortSignal | undefined): Promise<void> {
  return new Promise((resolve) => {
    if (signal?.aborted === true) return resolve()
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort)
      resolve()
    }, ms)
    const onAbort = () => {
      clearTimeout(timer)
      resolve()
    }
    signal?.addEventListener('abort', onAbort, { once: true })
  })
}

// ---------------------------------------------------------------------------
// Normalisation
// ---------------------------------------------------------------------------

/**
 * Turn one raw OSV vulnerability record into the reportable shape, given the
 * exact locked version the query was run for. `hasFix`/`fixedVersion` come
 * from the earliest `fixed` event among ranges that cover `version` (falling
 * back to the globally earliest `fixed` when no range explicitly covers it),
 * per the PROMPT spec ("affected ranges 里取最早 fixed").
 */
export function normalizeVulnerability(vuln: OsvVulnerability, version: string): NormalizedVuln {
  const aliases = vuln.aliases ?? []
  const cve = aliases.find((alias) => alias.startsWith('CVE-'))
  const ghsa = aliases.find((alias) => alias.startsWith('GHSA-'))
  const displayId = cve ?? ghsa ?? vuln.id
  const summary = truncate(vuln.summary ?? vuln.details ?? '', 120)

  const { score, qualitative } = severityOf(vuln)
  const covering = coveringFixedVersions(vuln, version)
  const earliestCovering = minVersion(covering)
  const fixedVersion = earliestCovering ?? earliestFixedGlobally(vuln)

  return {
    id: vuln.id,
    aliases,
    displayId,
    cve,
    ghsa,
    summary,
    cvss: score,
    severity: qualitative,
    fixedVersion,
    hasFix: fixedVersion !== undefined,
  }
}

function truncate(text: string, max: number): string {
  const normalized = text.replace(/\s+/g, ' ').trim()
  return normalized.length > max ? `${normalized.slice(0, max - 1)}…` : normalized
}

/** The affected ranges whose `introduced ≤ version < fixed` hold. */
function coveringFixeds(vuln: OsvVulnerability, version: string): string[] {
  const fixed: string[] = []
  for (const affected of vuln.affected ?? []) {
    for (const range of affected.ranges ?? []) {
      for (const event of range.events ?? []) {
        if (event.fixed !== undefined && versionInRange(version, event.introduced, event.fixed)) {
          fixed.push(event.fixed)
        }
      }
    }
  }
  return fixed
}

function coveringFixedVersions(vuln: OsvVulnerability, version: string): string[] {
  return coveringFixeds(vuln, version)
}

function earliestFixedGlobally(vuln: OsvVulnerability): string | undefined {
  const allFixed: string[] = []
  for (const affected of vuln.affected ?? []) {
    for (const range of affected.ranges ?? []) {
      for (const event of range.events ?? []) {
        if (event.fixed !== undefined) allFixed.push(event.fixed)
      }
    }
  }
  return minVersion(allFixed)
}

/**
 * CVSS score + qualitative label. Prefers the vulnerability-level
 * `database_specific.severity` (numeric CVSS string) or `cvss_v3.baseScore`,
 * falls back to the first per-affected `database_specific.severity`, then to
 * qualitative keywords (`CRITICAL`/`HIGH`/...).
 */
function severityOf(vuln: OsvVulnerability): { score: number | undefined; qualitative: Severity } {
  const db = vuln.database_specific
  const numeric = numericSeverity(db?.severity)
  if (numeric !== undefined) return { score: numeric, qualitative: labelForScore(numeric) }
  if (typeof db?.cvss_v3?.baseScore === 'number' && Number.isFinite(db.cvss_v3.baseScore)) {
    const score = db.cvss_v3.baseScore
    return { score, qualitative: labelForScore(score) }
  }
  for (const affected of vuln.affected ?? []) {
    const perAffected = numericSeverity(affected.database_specific?.severity)
    if (perAffected !== undefined) return { score: perAffected, qualitative: labelForScore(perAffected) }
  }
  const keyword = (db?.severity ?? '').toLowerCase()
  if (keyword === 'critical') return { score: undefined, qualitative: 'critical' }
  if (keyword === 'high') return { score: undefined, qualitative: 'high' }
  if (keyword === 'medium' || keyword === 'moderate') return { score: undefined, qualitative: 'medium' }
  if (keyword === 'low') return { score: undefined, qualitative: 'low' }
  return { score: undefined, qualitative: 'unknown' }
}

function numericSeverity(input: string | undefined): number | undefined {
  if (input === undefined || input === '') return undefined
  const trimmed = input.trim()
  if (/^\d+(\.\d+)?$/.test(trimmed)) {
    const value = Number(trimmed)
    if (Number.isFinite(value) && value >= 0 && value <= 10) return value
  }
  return undefined
}

/** Qualitative bucketing for CVSSv3 scores (critical ≥9, high ≥7, medium ≥4). */
export function labelForScore(score: number): Severity {
  if (score >= 9) return 'critical'
  if (score >= 7) return 'high'
  if (score >= 4) return 'medium'
  return 'low'
}

/** True when the locked version is a valid semver (used by the report footnote). */
export function isParsableVersion(version: string): boolean {
  const parts = parseSemver(version)
  return parts !== null && Number.isInteger(parts.major)
