export interface SemverParts {
  /** Major version (defaults to 0 when a string like `"0"` is parsed). */
  major: number
  minor: number
  patch: number
  /**
   * Pre-release identifiers, or `null` for a stable release. An empty array
   * is never produced — `null` is the stable marker.
   */
  prerelease: string[] | null
}

/**
 * Parse a loose version string such as `v1.2.3`, `1.2.3-beta.1`, `1.2.3+build`
 * or OSV's bare `"0"` / `"1.2"` forms into numeric parts. Returns `null` when
 * the string does not start with a semver shape.
 */
export function parseSemver(input: string): SemverParts | null {
  const raw = String(input).trim()
  if (raw === '') return null
  const withoutV = raw.startsWith('v') ? raw.slice(1) : raw
  // Split off build metadata first; it never participates in ordering.
  const withoutBuild = withoutV.split('+')[0] ?? withoutV
  const [coreWithPre, ...maybeJunk] = withoutBuild.split('-')
  if (maybeJunk.length > 1 || coreWithPre === undefined) return null
  const coreParts = coreWithPre.split('.')
  const numbers = coreParts.slice(0, 3).map((part) => {
    if (!/^\d+$/.test(part)) return Number.NaN
    return Number(part)
  })
  if (numbers.some((n) => Number.isNaN(n))) return null
  const [major = 0, minor = 0, patch = 0] = numbers
  const prerelease = coreWithPre === withoutBuild
    ? null
    : (maybeJunk[0] ?? '').split('.').filter((p) => p !== '')
  return { major, minor, patch, prerelease }
}

function isValidSemver(parts: SemverParts): boolean {
  return (
    Number.isInteger(parts.major)
    && Number.isInteger(parts.minor)
    && Number.isInteger(parts.patch)
    && parts.major >= 0 && parts.minor >= 0 && parts.patch >= 0
  )
}

/**
 * Compare two parsed versions. Returns a negative number when `a < b`, zero
 * when equal, a positive number when `a > b`, per the SemVer 2.0 ordering
 * rules (numeric pre-release identifiers sort before alphanumeric ones, and a
 * shorter pre-release list sorts before a longer one with an equal prefix).
 */
export function compareParsed(a: SemverParts, b: SemverParts): number {
  const base = compareNumeric(a, b)
  if (base !== 0) return base
  return comparePrerelease(a.prerelease, b.prerelease)
}

function compareNumeric(a: SemverParts, b: SemverParts): number {
  if (a.major !== b.major) return a.major - b.major
  if (a.minor !== b.minor) return a.minor - b.minor
  return a.patch - b.patch
}

function comparePrerelease(a: string[] | null, b: string[] | null): number {
  // Stable releases rank above any pre-release of the same core version.
  if (a === null && b === null) return 0
  if (a === null) return 1
  if (b === null) return -1
  const len = Math.max(a.length, b.length)
  for (let i = 0; i < len; i++) {
    const ai = a[i]
    const bi = b[i]
    if (ai === undefined && bi === undefined) return 0
    if (ai === undefined) return -1
    if (bi === undefined) return 1
    const cmp = compareIdentifier(ai, bi)
    if (cmp !== 0) return cmp
  }
  return 0
}

function compareIdentifier(a: string, b: string): number {
  const aNum = /^\d+$/.test(a) ? Number(a) : undefined
  const bNum = /^\d+$/.test(b) ? Number(b) : undefined
  if (aNum !== undefined && bNum !== undefined) return aNum - bNum
  if (aNum !== undefined) return -1 // numeric identifiers sort lower
  if (bNum !== undefined) return 1
  return a < b ? -1 : a > b ? 1 : 0
}

/**
 * Compare two loose version strings (each parsed and validated). Returns
 * `null` when either side is not a valid semver, so callers can treat the
 * comparison as "unknown" instead of emitting a wrong ordering.
 */
export function compareVersions(a: string, b: string): number | null {
  const pa = parseSemver(a)
  const pb = parseSemver(b)
  if (pa === null || !isValidSemver(pa)) return null
  if (pb === null || !isValidSemver(pb)) return null
  return compareParsed(pa, pb)
}

/**
 * Pick the smallest of several loose version strings under {@link compareVersions}.
 * Unparsable or invalid strings are ignored; `undefined` is returned when
 * nothing parsable remains.
 */
export function minVersion(versions: readonly string[]): string | undefined {
  let best: string | undefined
  for (const candidate of versions) {
    if (best === undefined) {
      best = candidate
      continue
    }
    const cmp = compareVersions(candidate, best)
    if (cmp !== null && cmp < 0) best = candidate
  }
  return best
}

/**
 * Membership test used by the "confirmed affected" filter: a version is inside
 * a range described by `introduced`/`fixed` events when `introduced ≤ version
 * < fixed`. OSV emits `introduced` as the empty string `""` on some datapoints
 * meaning "from the beginning" — treated as version 0.0.0.
 */
export function versionInRange(
  version: string,
  introduced: string | undefined,
  fixed: string | undefined,
): boolean {
  const v = parseSemver(version)
  if (v === null || !isValidSemver(v)) return false
  const introducedParsed = introduced === undefined || introduced === ''
    ? { major: 0, minor: 0, patch: 0, prerelease: null as string[] | null }
    : parseSemver(introduced)
  if (introducedParsed === null || !isValidSemver(introducedParsed)) return false
  if (compareParsed(v, introducedParsed) < 0) return false
  if (fixed === undefined || fixed === '') return true // no upper bound: affected from `introduced`
  const fixedParsed = parseSemver(fixed)
  if (fixedParsed === null || !isValidSemver(fixedParsed)) return true // unparsable upper bound: assume affected
  return compareParsed(v, fixedParsed) < 0
