import type { JsonValue } from '@deepseek-ai/dsh-tools'
import type { NormalizedVuln, OsvFailure, OsvQueryPackage } from './osv-client.js'
import { compareVersions } from './semver.js'

/** One affected package: the lockfile entry plus its confirmed vulns. */
export interface Finding {
  ecosystem: string
  /** Basename of the lockfile the package came from. */
  lockfile: string
  name: string
  version: string
  vulns: NormalizedVuln[]
  /** True when at least one vuln has a known fix version. */
  hasFix: boolean
}

/** SBOM summary produced by `effort: 'full'`. */
export interface SbomSummary {
  /** Per-ecosystem distinct-package counts. */
  ecosystems: Array<{ ecosystem: string; packageCount: number }>
  /** Deduplicated package inventory (name + version + ecosystem). */
  packages: Array<{ ecosystem: string; name: string; version: string }>
}

/** Aggregate counters shown in the report header. `verifier`-口径 counts only confirmed findings. */
export interface Summary {
  /** Distinct package entries queried. */
  scannedPackages: number
  /** Distinct packages with at least one confirmed vuln. */
  affectedPackages: number
  /** Affected packages carrying at least one high/critical vuln. */
  highCount: number
  /** Affected packages for which a fix version is known. */
  fixableCount: number
  /** Affected packages with no known fix. */
  unfixableCount: number
  /** Number of structured errors collected during the scan. */
  errorCount: number
}

/** One lockfile record in `scanned`. */
export interface ScannedLockfile {
  ecosystem: string
  /** Display path of the lockfile (workspace-relative when possible). */
  path: string
  packageCount: number
}

/** The canonical tool output value (JSON-safe by construction). */
export interface ScanReport {
  scanned: {
    effort: 'fast' | 'full'
    /** Root path that was scanned (as resolved by `ctx.fs`). */
    root: string
    lockfiles: ScannedLockfile[]
    /** Total distinct package entries across lockfiles. */
    packageCount: number
    /** Present only when effort was `full`. */
    sbom: SbomSummary | null
  }
  findings: Finding[]
  summary: Summary
  errors: OsvFailure[]
}

/**
 * Build the report from scan ingredients. Pure: no I/O, no clock.
 */
export function buildReport(input: {
  effort: 'fast' | 'full'
  root: string
  lockfiles: ScannedLockfile[]
  queries: OsvQueryPackage[]
  vulnsByQuery: NormalizedVuln[][]
  errors: OsvFailure[]
}): ScanReport {
  const findings = composeFindings(input.queries, input.vulnsByQuery, input.lockfiles)
  const packageCount = input.queries.length
  const sbom = input.effort === 'full'
    ? buildSbom(input.queries)
    : null
  return {
    scanned: {
      effort: input.effort,
      root: input.root,
      lockfiles: input.lockfiles,
      packageCount,
      sbom,
    },
    findings,
    summary: summarize(findings, packageCount, input.errors.length),
    errors: input.errors,
  }
}

/** Convert per-query OSV results into `Finding` rows (only confirmed hits). */
function composeFindings(
  queries: OsvQueryPackage[],
  vulnsByQuery: NormalizedVuln[][],
  lockfiles: ScannedLockfile[],
): Finding[] {
  const ecosystemFor = new Map(lockfiles.map((lf) => [lf.ecosystem, lf.path]))
  const findings: Finding[] = []
  queries.forEach((query, index) => {
    const vulns = vulnsByQuery[index] ?? []
    if (vulns.length === 0) return
    findings.push({
      ecosystem: query.ecosystem,
      lockfile: ecosystemFor.get(query.ecosystem) ?? 'unknown',
      name: query.name,
      version: query.version,
      vulns,
      hasFix: vulns.some((v) => v.hasFix),
    })
  })
  return findings
}

function buildSbom(queries: OsvQueryPackage[]): SbomSummary {
  const byEcosystem = new Map<string, Set<string>>()
  const packages: Array<{ ecosystem: string; name: string; version: string }> = []
  for (const query of queries) {
    const bucket = byEcosystem.get(query.ecosystem) ?? new Set<string>()
    const id = `${query.name}@${query.version}`
    if (!bucket.has(id)) {
      bucket.add(id)
      packages.push({ ecosystem: query.ecosystem, name: query.name, version: query.version })
    }
    byEcosystem.set(query.ecosystem, bucket)
  }
  return {
    ecosystems: [...byEcosystem.entries()]
      .map(([ecosystem, set]) => ({ ecosystem, packageCount: set.size }))
      .sort((a, b) => b.packageCount - a.packageCount),
    packages: packages.sort((a, b) => a.ecosystem.localeCompare(b.ecosystem) || a.name.localeCompare(b.name)),
  }
}

/** Summary counters over confirmed findings. */
export function summarize(findings: readonly Finding[], scannedPackages: number, errorCount: number): Summary {
  const affectedPackages = findings.length
  let highCount = 0
  let fixableCount = 0
  let unfixableCount = 0
  for (const finding of findings) {
    const hasHigh = finding.vulns.some((v) => v.severity === 'high' || v.severity === 'critical')
    if (hasHigh) highCount += 1
    if (finding.hasFix) fixableCount += 1
    else unfixableCount += 1
  }
  return {
    scannedPackages,
    affectedPackages,
    highCount,
    fixableCount,
    unfixableCount,
    errorCount,
  }
}

/**
 * Render the report as model-facing markdown: summary line + finding table +
 * remediation section (+ SBOM summary for `full`). This is the `output.render`
 * body; the value itself stays the JSON report.
 */
export function renderMarkdown(report: ScanReport): string {
  const lines: string[] = []
  lines.push('# 依赖漏洞扫描报告')
  lines.push('')
  lines.push(
    `- **范围**: \`${report.scanned.root}\`（effort: \`${report.scanned.effort}\`，`
    + `扫描 ${report.scanned.lockfiles.length} 个锁文件，${report.scanned.packageCount} 个包）`,
  )
  const summary = report.summary
  lines.push(
    `- **汇总**: 受影响包 **${summary.affectedPackages}**，高危 ${summary.highCount}，`
    + `可修复 ${summary.fixableCount}，无修复版 ${summary.unfixableCount}`,
  )
  lines.push('')

  if (report.errors.length > 0) {
    lines.push('> ⚠️ 扫描期间出现错误（以下查询可能不完整）：')
    for (const error of report.errors) {
      lines.push(`> - \`${error.kind}\`${error.status !== undefined ? ` (HTTP ${error.status})` : ''}: ${error.message}`)
    }
    lines.push('')
  }

  if (summary.affectedPackages === 0) {
    lines.push('**0 受影响** — 锁文件中的包均未发现已知漏洞（OSV）。')
    lines.push('')
  } else {
    lines.push('| 包 | 当前版本 | 漏洞 ID | 摘要 | CVSS | 修复版本 |')
    lines.push('| --- | --- | --- | --- | --- | --- |')
    for (const finding of report.findings) {
      const cell = (text: string) => escapeCell(text)
      for (const vuln of finding.vulns) {
        const fixCell = vuln.hasFix
          ? `√ 有修复版 \`${vuln.fixedVersion}\``
          : '无修复版'
        lines.push(
          `| ${cell(finding.name)} | ${cell(finding.version)} | ${cell(vuln.displayId)} `
          + `| ${cell(vuln.summary)} | ${vuln.cvss !== undefined ? vuln.cvss.toFixed(1) : vuln.severity} | ${fixCell} |`,
        )
      }
    }
    lines.push('')
    lines.push('### 修复建议（未自动修改任何文件，确认后自行执行）')
    const commands = remediationCommands(report.findings)
    for (const command of commands) {
      lines.push(`- \`${command}\``)
    }
    lines.push('')
  }

  if (report.scanned.sbom !== null) {
    const sbom = report.scanned.sbom
    lines.push('### SBOM 摘要（effort=full）')
    for (const ecosystem of sbom.ecosystems) {
      lines.push(`- ${ecosystem.ecosystem}: ${ecosystem.packageCount} 个包`)
    }
    lines.push('')
  }

  lines.push(
    '_数据源: OSV (api.osv.dev)，免费无 key。仅展示锁文件中确认存在的漏洞（当前版本落在 affected 区间内）；修复建议仅供参考，不自动改写锁文件。_',
  )
  return lines.join('\n')
}

function escapeCell(text: string): string {
  return text.replace(/\|/g, '\\|').replace(/\n/g, ' ')
}

/** Per-ecosystem remediation command for each confirmed (package, earliest fix). */
export function remediationCommands(findings: readonly Finding[]): string[] {
  const commands: string[] = []
  for (const finding of findings) {
    const fixed = earliestFix(finding.vulns)
    if (fixed === undefined) {
      commands.push(`${finding.name}@{${finding.version}} 无修复版，需联系上游或制定缓解措施`)
      continue
    }
    const command = remediationCommand(finding.ecosystem, finding.name, fixed)
    commands.push(`${command}   # ${finding.name} ${finding.version} → ${fixed}`)
  }
  return commands
}

export function remediationCommand(ecosystem: string, name: string, fixed: string): string {
  const version = fixed.replace(/^v/, '')
  switch (ecosystem) {
    case 'npm':
      return `npm install ${name}@${version}`
    case 'PyPI':
      return `pip install ${name}==${version}`
    case 'Go':
      return `go get ${name}@${fixed}`
    case 'crates.io':
      return `cargo update -p ${name} --precise ${version}`
    case 'Maven': {
      const [, artifact] = name.split(':')
      if (artifact !== undefined && artifact !== '') {
        return `mvn versions:use-dep-version -Dincludes=${name} -DdepVersion=${version} -DforceVersion=true`
      }
      return `mvn versions:use-latest-versions -Dincludes=${name}`
    }
    case 'NuGet':
      return `dotnet add package ${name} --version ${version}`
    case 'RubyGems':
      return `bundle update ${name}`
    default:
      return `升级 ${name} 至 ${fixed}（按生态手动更新构建文件）`
  }
}

function earliestFix(vulns: readonly NormalizedVuln[]): string | undefined {
  let best: string | undefined
  for (const vuln of vulns) {
    if (!vuln.hasFix || vuln.fixedVersion === undefined) continue
    if (best === undefined) {
      best = vuln.fixedVersion
      continue
    }
    const cmp = compareVersions(vuln.fixedVersion, best)
    if (cmp !== null && cmp < 0) best = vuln.fixedVersion
  }
  return best
}

/**
 * Replayable presentation projection: the whole report is already lossless
 * JSON, so the projector returns it unchanged (persisted under `tool/result`
 * `meta` for card replay). Pure function of `(args, value)`.
 */
export function buildPresentationMeta(_args: unknown, value: ScanReport): JsonValue {
  // The whole report is already lossless JSON; only the interface shape needs
  // a boundary cast to satisfy `JsonValue`.
  return value as unknown as JsonValue
